/**
 * Returns permits issued in the given borough within the last N days.
 * @summary Recent permits by borough
 */
export const getGetRecentPermitsUrl = (params: GetRecentPermitsParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/permits/recent?${stringifiedParams}`
    : `/api/permits/recent`;
};

